import java.util.List;

public class Gradebook {
    public static double average(List<Integer> scores) {
        double sum = 0;
        for (int s : scores) sum += s;
        return scores.isEmpty() ? 0 : sum / scores.size();
    }

    public static long countPassing(List<Integer> scores, int passMark) {
        return scores.stream().filter(s -> s >= passMark).count();
    }
}

